    public static function key(string $s):string{return 'reimbursement_'.substr(hash('sha256',$s),0,24);}
    public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$v)$out[self::key($s)]=$en?$v:$s;return$out;}
    public static function text(string $source,array $messages,array $values=[]):string{$text=$messages[self::key($source)]??$source;foreach($values as$key=>$value)if(is_scalar($value))$text=str_replace('{'.$key.'}',(string)$value,$text);return$text;}
